import importlib, sys, shutil, subprocess

print("Python:", sys.version)
for mod in ['openpyxl', 'pandas', 'xlsxwriter', 'xlrd']:
    try:
        importlib.import_module(mod)
        print(f"{mod}: available")
    except ImportError:
        print(f"{mod}: NOT available")

for tool in ['libreoffice', 'soffice', 'python3', 'pip', 'pip3']:
    print(f"{tool}: {shutil.which(tool)}")

try:
    r = subprocess.run([sys.executable, '-m', 'pip', '--version'], capture_output=True, text=True, timeout=30)
    print("pip version:", r.stdout.strip() or r.stderr.strip())
except Exception as e:
    print("pip check failed:", e)

import zipfile
import re
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
      "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships"}

path = "budget.xlsx"
z = zipfile.ZipFile(path)
print("ZIP ENTRIES:", z.namelist())

shared = []
if "xl/sharedStrings.xml" in z.namelist():
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in root.findall("m:si", NS):
        text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
        shared.append(text)

wbroot = ET.fromstring(z.read("xl/workbook.xml"))
rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
relmap = {}
for rel in rels:
    relmap[rel.get("Id")] = rel.get("Target")

sheetfiles = []
for sh in wbroot.find("m:sheets", NS):
    rid = sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
    target = relmap.get(rid, "")
    if not target.startswith("xl/"):
        target = "xl/" + target.lstrip("/")
    sheetfiles.append((sh.get("name"), target))

def col_to_idx(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    letters, row = m.group(1), int(m.group(2))
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx, row

for name, target in sheetfiles:
    print(f"\n=== SHEET: {name} ===")
    root = ET.fromstring(z.read(target))
    cells = {}
    for c in root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c"):
        ref = c.get("r")
        t = c.get("t")
        v = c.find("m:v", NS)
        val = v.text if v is not None else None
        if t == "s" and val is not None:
            val = shared[int(val)]
        elif val is not None:
            try:
                val = float(val)
                if val == int(val):
                    val = int(val)
            except ValueError:
                pass
        if ref:
            cells[ref] = val
    maxc, maxr = 0, 0
    for ref in cells:
        ci, ri = col_to_idx(ref)
        maxc, maxr = max(maxc, ci), max(maxr, ri)
    grid = [[""] * maxc for _ in range(maxr)]
    for ref, val in cells.items():
        ci, ri = col_to_idx(ref)
        grid[ri - 1][ci - 1] = val
    for r in grid:
        print(r)

